import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlTitleComponent } from '@domg-wc/components/atom';
import { VlInputSliderComponent } from '@domg-wc/components/block';
import {
    VlMap,
    VlMapActionControls,
    VlMapBaseLayerGRB,
    VlMapBaseLayerGRBGray,
    VlMapBaseLayerGRBOrtho,
    VlMapDeleteAction,
    VlMapDrawLineAction,
    VlMapDrawPointAction,
    VlMapDrawPolygonAction,
    VlMapFeaturesLayer,
    VlMapLayerCircleStyle,
    VlMapLayerStyle,
    VlMapLayerSwitcher,
    VlMapLegend,
    VlMapMeasureAction,
    VlMapMeasureControl,
    VlMapModifyAction,
    VlMapOverviewMap,
    VlMapSelectAction,
    VlMapSideSheet,
} from '@domg-wc/map';

// De import registreert de elementen; registerWebComponents houdt de klassen in de bundel.
registerWebComponents([
    VlButtonComponent,
    VlTitleComponent,
    VlInputSliderComponent,
    VlMap,
    VlMapActionControls,
    VlMapBaseLayerGRB,
    VlMapBaseLayerGRBGray,
    VlMapBaseLayerGRBOrtho,
    VlMapDeleteAction,
    VlMapDrawLineAction,
    VlMapDrawPointAction,
    VlMapDrawPolygonAction,
    VlMapFeaturesLayer,
    VlMapLayerCircleStyle,
    VlMapLayerStyle,
    VlMapLayerSwitcher,
    VlMapLegend,
    VlMapMeasureAction,
    VlMapMeasureControl,
    VlMapModifyAction,
    VlMapOverviewMap,
    VlMapSelectAction,
    VlMapSideSheet,
]);

// De hulpfuncties uit de TypeScript code onder de story, zonder types en zonder export.
const getActionElement = (name) => getLastElementByClassName(`${name}-action`);
const getToggleButton = (name) => getLastElementByClassName(`${name}-toggle-button`);
const actionIdentifiers = ['draw-point', 'draw-line', 'draw-polygon', 'modify', 'delete'];

// Make sure the class that is given is unique and is not being used in other stories of the component.
const getLastElementByClassName = (className) => {
    const items = document.getElementsByClassName(className);
    return items[items.length - 1];
};

const handleActiveActionChange = ({ detail: { previous, current } }) => {
    // Activate/deactivate external controls when an action changes its state
    actionIdentifiers.forEach((actionIdentifier) => {
        if (previous === getActionElement(actionIdentifier)) {
            getToggleButton(actionIdentifier).on = false;
        } else if (current === getActionElement(actionIdentifier)) {
            getToggleButton(actionIdentifier).on = true;
        }
    });
};

const handleLayerVisibleChange = ({ detail: { layer, visible } }) => {
    // Enable/disable external controls when an action changes its state
    const layerActions = layer.getElementsByClassName('action');

    for (const layerAction of layerActions) {
        actionIdentifiers.forEach((actionIdentifier) => {
            if (layerAction === getActionElement(actionIdentifier)) {
                getToggleButton(actionIdentifier).disabled = !visible;
            }
        });
    }
};

const handleOpacitySliderChange = ({ detail: { value } }) => {
    // Set the opacity of all feature layers based on the value of the input slider
    const featureLayers = document.querySelectorAll('vl-map-features-layer');

    featureLayers?.forEach((layer) => {
        layer.setAttribute('opacity', value / 100);
    });
};

const map = document.querySelector('#map-playground');

// De laag Shapes krijgt een punt, een lijn en een polygoon als GeoJSON in Lambert 72, het coördinatenstelsel van de
// kaart. De setter van features zet het object als JSON-string in het attribuut features.
map.querySelector('vl-map-features-layer[name="Shapes"]').features = {
    type: 'FeatureCollection',
    features: [
        {
            type: 'Feature',
            id: 1,
            geometry: { type: 'Point', coordinates: [210000, 190000] },
        },
        {
            type: 'Feature',
            id: 2,
            geometry: {
                type: 'LineString',
                coordinates: [
                    [170000, 170000],
                    [150000, 206000],
                ],
            },
        },
        {
            type: 'Feature',
            id: 3,
            geometry: {
                type: 'Polygon',
                coordinates: [
                    [
                        [44000, 171000],
                        [100000, 171000],
                        [100000, 205000],
                        [44000, 205000],
                        [44000, 171000],
                    ],
                ],
            },
        },
    ],
};

// Zoals in de story: de toggle-knoppen volgen de actieve actie, de knoppen van een onzichtbare kaartlaag schakelen
// uit, en de slider zet de opacity van de kaartlagen.
map.addEventListener('vl-active-action-changed', handleActiveActionChange);
map.addEventListener('vl-layer-visible-changed', handleLayerVisibleChange);
map.querySelector('vl-input-slider').addEventListener('vl-change-value', handleOpacitySliderChange);

// Meten starten en stoppen met de property active van vl-map-measure-action.
document.querySelector('#measure-start-button').addEventListener('click', () => {
    getActionElement('measure').active = true;
});
document.querySelector('#measure-stop-button').addEventListener('click', () => {
    getActionElement('measure').active = false;
});

// Een toggle-knop zet zijn eigen on om voor de click deze listener bereikt; de actie volgt de knop.
actionIdentifiers.forEach((actionIdentifier) => {
    getToggleButton(actionIdentifier).addEventListener('click', () => {
        getActionElement(actionIdentifier).active = getToggleButton(actionIdentifier).on;
    });
});
